export {
  MessageDigest,
  type MessageDigestEntry,
  type MessageDigestProps,
} from "./message-digest"

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Initials for a contact: the first letter of the first and last
 * whitespace-separated parts of the name, so "Bruce Wayne" reads "BW" the way
 * a contact card would abbreviate it. A single-word name keeps one letter, and
 * an empty name gets nothing rather than a stray glyph.
 */
export function initialsFrom(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (parts.length === 0) return ""
  const first = [...parts[0]!][0] ?? ""
  const last = parts.length > 1 ? ([...parts[parts.length - 1]!][0] ?? "") : ""
  return (first + last).toUpperCase()
}

/**
 * Where a corner marker sits: centred on the circle's own trailing edge at
 * 45°, which
 * for a circle of radius r is r/√2 — 35.36% of the box — from its centre, so
 * the ring runs through the marker's middle. Hanging a marker off the square
 * bounding box instead leaves it floating diagonally clear of the edge,
 * because the box's corner is outside the circle by 0.29r.
 */
const markerPosition =
  // `start-*` is the logical inset, so the corner mirrors with text
  // direction. The centring shift has to mirror with it: an unscoped
  // `-translate-x-1/2` would push the marker off the circle in RTL, where
  // the inset anchors its trailing edge instead of its leading one.
  "absolute start-[85.36%] ltr:-translate-x-1/2 rtl:translate-x-1/2 -translate-y-1/2"

export interface ContactAvatarProps extends React.ComponentProps<"span"> {
  /** The contact's name; seeds the initials when no photo renders. */
  name: string
  /** Photo to draw; the initials take over while it is absent or fails. */
  src?: string
  /** Overrides the initials derived from `name`. */
  initials?: string
  /** Replaces the circle's contents entirely — a RandomAvatar, a brand mark. */
  children?: React.ReactNode
  /** A small glyph badged on the circle's trailing bottom corner. */
  badge?: React.ReactNode
  /**
   * Marks the contact as having something unread, with a dot in the circle's
   * trailing bottom corner — the same slot a channel mark sits in, which is
   * where the eye already looks. A circle carrying both keeps the mark there
   * and moves the dot to the top corner, so neither is lost. Decoration
   * only: the surface that sets it owes readers the same fact in text.
   */
  unread?: boolean
  /** Extra classes for the badge, for callers that scale it with the circle. */
  badgeClassName?: string
}

/**
 * The identity circle shared by every surface in this family: a photo, the
 * contact's initials, or whatever the caller puts in its place, with an
 * optional channel badge on one corner and an unread dot on the other. Both
 * markers are decoration: a badge that carries meaning is spelled out by the
 * row that owns it, in its own reading order, not by this circle.
 * Sizing belongs to the caller, through
 * `className` — the circle only owns its shape, its fallback, and the fact
 * that neither the initials nor the badge reach assistive technology, because
 * the name they abbreviate is always written out beside them.
 */
export function ContactAvatar({
  name,
  src,
  initials,
  children,
  badge,
  badgeClassName,
  unread = false,
  className,
  ...props
}: ContactAvatarProps) {
  const [failedSrc, setFailedSrc] = React.useState<string | null>(null)
  const showsImage = children == null && src != null && src !== failedSrc
  return (
    <span
      data-slot="contact-avatar"
      className={cn("relative shrink-0", className)}
      {...props}
    >
      {/* The hairline and the full-strength initials are both load-bearing:
          these rows sit on a muted tile, where a muted circle on muted fill
          disappears and muted-on-muted initials sit at the 4.5:1 floor —
          legible by the letter of the gate, faint in the hand. */}
      <span className="flex size-full select-none items-center justify-center overflow-hidden rounded-full border border-border bg-muted nessa-text-2 font-medium text-foreground">
        {children ??
          (showsImage ? (
            <img
              src={src}
              alt=""
              className="size-full object-cover"
              onError={() => setFailedSrc(src ?? null)}
            />
          ) : (
            <span aria-hidden="true">{initials ?? initialsFrom(name)}</span>
          ))}
      </span>
      {unread ? (
        // Centred on the ring itself, not hung off the bounding box: the
        // hairline in the surrounding surface's own colour then reads as a
        // gap punched in the circle's edge, and keeps the dot legible
        // against a photo as well as against the muted fallback.
        <span
          aria-hidden="true"
          data-slot="contact-avatar-unread"
          data-corner={badge == null ? "bottom" : "top"}
          className={cn(
            markerPosition,
            "size-2.5 rounded-full border border-card bg-(--nessa-chat-accent)",
            // The mark, when there is one, owns the bottom corner it was
            // designed for; the dot steps up rather than stacking on it.
            badge == null ? "top-[85.36%]" : "top-[14.64%]",
          )}
        />
      ) : null}
      {badge == null ? null : (
        <span
          aria-hidden="true"
          data-slot="contact-avatar-badge"
          className={cn(
            markerPosition,
            "top-[85.36%] flex size-4 items-center justify-center overflow-hidden rounded-full border border-card bg-muted text-muted-foreground [&_svg]:size-2.5",
            badgeClassName,
          )}
        >
          {badge}
        </span>
      )}
    </span>
  )
}

"use client"

import * as React from "react"

import { IMessageLogo } from "./imessage-logo"
import { MailLogo } from "./mail-logo"

/**
 * The channels this module ships a mark for, matched against the display name
 * the card was given. Matching is on whole words, so "Gmail" never picks up
 * Apple's Mail mark from the letters inside it, while "Apple Mail" and
 * "Mail (iCloud)" do.
 */
const builtInMarks: readonly {
  words: readonly string[]
  render: () => React.ReactElement
}[] = [
  { words: ["messages", "imessage"], render: () => <IMessageLogo /> },
  { words: ["mail"], render: () => <MailLogo /> },
]

/** Splits a channel name into lowercase word tokens. */
function channelWords(channel: string): string[] {
  return channel.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean)
}

/**
 * The mark for a channel this module knows, or `null` for one it does not.
 *
 * These are trademarks, so the rule is deliberately narrow: a card badges a
 * mark only when its own `channel` names that service. Every other channel
 * shows no badge until its host passes one — a wrong logo is worse than none.
 */
export function builtInChannelMark(channel: string): React.ReactElement | null {
  const words = channelWords(channel)
  const match = builtInMarks.find((candidate) =>
    candidate.words.some((word) => words.includes(word)),
  )
  return match ? match.render() : null
}

"use client"

import * as React from "react"
import { Check } from "lucide-react"

import { cn } from "@/lib/utils"
import { ContactAvatar } from "./contact-avatar"

export interface ContactChoice {
  /** Identifies the contact across selection. */
  id: string
  /** The display name, the row's only required content. */
  name: string
  /**
   * What tells two same-named contacts apart — a number, an address, a
   * company. Shown muted under the name, and read as part of the row.
   */
  detail?: string
  /** Photo for the row's avatar; initials show while it is absent or fails. */
  avatarSrc?: string
  /** Overrides the initials derived from `name`. */
  initials?: string
  /** A glyph badged on the avatar — the app this contact is reachable on. */
  badge?: React.ReactNode
  /**
   * What that badge means, in words — "on WhatsApp". Required in practice
   * whenever `badge` is what tells two same-named contacts apart: the mark
   * is drawn as decoration, and these rows carry no channel text of their
   * own, so without this the difference reaches no one who cannot see it.
   */
  badgeLabel?: string
}

export interface ContactChoicesProps
  extends Omit<React.ComponentProps<"div">, "onSelect" | "title" | "children"> {
  /** The contacts to offer, in the order they should appear. */
  contacts: readonly ContactChoice[]
  /**
   * The question above the list — "Which Bruce should I address the message
   * to?". Pass `null` when the surrounding surface already asks.
   */
  title?: React.ReactNode
  /** The chosen contact's id, or `null` while the question is open. */
  value?: string | null
  /** Fires with the chosen contact's id. */
  onValueChange?: (id: string) => void
  /**
   * Accessible name for the list itself. Defaults to the title when it is a
   * plain string, and to "Contacts" otherwise.
   */
  label?: string
  /** Shown in place of the list when `contacts` is empty. */
  emptyMessage?: string
}

/**
 * The disambiguation step before a message goes out: an agent found more than
 * one person matching what was asked and offers them as rows to choose from.
 * Each row is a button carrying the contact's avatar, name, and whatever tells
 * it apart from its namesakes; the chosen one keeps a check and is marked
 * `aria-current`, so the answer stays legible after the list stops being a
 * question.
 *
 * The list sizes itself to its container rather than the viewport — rows stay
 * single-line and truncate in a narrow rail, and step up in avatar size and
 * type from about 24rem of width. Choosing is the host's: the picker holds no
 * selection of its own and filters nothing.
 */
function ContactChoices({
  contacts,
  title = "Who should I send it to?",
  value = null,
  onValueChange,
  label,
  emptyMessage = "No matching contacts",
  className,
  ...props
}: ContactChoicesProps) {
  const titleId = React.useId()
  // The question names the list. `label` overrides it; otherwise the title
  // element itself is the name, whatever it is made of — a title that is
  // markup rather than a plain string must not fall back to a generic word
  // that tells a screen-reader user nothing about what the rows answer.
  const titled = title != null && label === undefined
  return (
    <div
      data-slot="contact-choices"
      className={cn(
        "@container/contact-choices flex w-full min-w-0 flex-col gap-2 font-sans",
        className,
      )}
      {...props}
    >
      {title == null ? null : (
        <p
          id={titleId}
          data-slot="contact-choices-title"
          className="min-w-0 nessa-text-3 font-medium text-foreground @[24rem]/contact-choices:nessa-text-4"
        >
          {title}
        </p>
      )}
      {contacts.length === 0 ? (
        <p className="m-0 px-1 py-4 nessa-text-3 text-muted-foreground">
          {emptyMessage}
        </p>
      ) : (
        <ul
          role="list"
          aria-labelledby={titled ? titleId : undefined}
          aria-label={titled ? undefined : (label ?? "Contacts")}
          data-slot="contact-choices-list"
          className="m-0 flex list-none flex-col gap-2 p-0"
        >
          {contacts.map((contact) => {
            const selected = contact.id === value
            return (
              <li key={contact.id} className="min-w-0">
                <button
                  type="button"
                  aria-current={selected ? "true" : undefined}
                  data-slot="contact-choices-item"
                  data-selected={selected || undefined}
                  onClick={() => onValueChange?.(contact.id)}
                  className={cn(
                    "flex w-full min-w-0 items-center gap-3 rounded-2xl border-0 bg-muted/60 px-3 py-2.5 text-start outline-none transition-colors [transition-duration:var(--nessa-motion-duration-fast)] hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:transition-none @[24rem]/contact-choices:px-3.5 @[24rem]/contact-choices:py-3",
                    selected && "bg-accent text-accent-foreground",
                  )}
                >
                  <ContactAvatar
                    name={contact.name}
                    src={contact.avatarSrc}
                    initials={contact.initials}
                    badge={contact.badge}
                    className="size-9 @[24rem]/contact-choices:size-10"
                  />
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span
                      data-slot="contact-choices-name"
                      className="truncate nessa-text-3 font-medium text-foreground @[24rem]/contact-choices:nessa-text-4"
                    >
                      {contact.name}
                      {contact.badgeLabel == null ? null : (
                        // After the name, so the row reads "Clark Kent on
                        // Mail" rather than leading with the account. The
                        // badge itself is decoration; this is the only place
                        // its meaning exists in text.
                        <span className="sr-only"> {contact.badgeLabel}</span>
                      )}
                    </span>
                    {contact.detail ? (
                      <span
                        data-slot="contact-choices-detail"
                        className="truncate nessa-text-2 text-muted-foreground"
                      >
                        {contact.detail}
                      </span>
                    ) : null}
                  </span>
                  {selected ? (
                    <Check
                      aria-hidden="true"
                      className="size-4 shrink-0 text-foreground"
                    />
                  ) : null}
                </button>
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}

export { ContactChoices }

"use client"

import * as React from "react"
import { Check, LoaderCircle, TriangleAlert, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "../button"
import { builtInChannelMark } from "./channel-marks"
import { ContactAvatar } from "./contact-avatar"

/**
 * Where the request stands.
 *
 * - `pending` — the decision is the person's to make; both actions are live.
 * - `sending` — the host is dispatching; the actions stay visible but inert.
 * - `sent`, `cancelled`, `failed` — resolved; the actions give way to a
 *   status line, because the decision is no longer available to take.
 */
export type MessageApprovalStatus =
  | "pending"
  | "sending"
  | "sent"
  | "cancelled"
  | "failed"

/** The resolved states: the decision is over and the actions come down. */
const resolvedStatuses: ReadonlySet<MessageApprovalStatus> = new Set([
  "sent",
  "cancelled",
  "failed",
])

/** Default status wording, replaceable through `statusLabel`. */
const statusLabels: Record<MessageApprovalStatus, string> = {
  pending: "",
  sending: "Sending…",
  sent: "Sent",
  cancelled: "Not sent",
  failed: "Couldn't send",
}

/** The glyph each resolved state carries beside its wording. */
const statusIcons = {
  sent: Check,
  cancelled: X,
  failed: TriangleAlert,
} as const

/**
 * Reports whether an element's content overflows its height cap. A capped,
 * scrolling region owes keyboard users a tab stop, but only while it can
 * actually scroll — so the answer is re-measured after every commit and
 * whenever the element resizes.
 */
function useOverflowing(ref: React.RefObject<HTMLElement | null>) {
  const [overflowing, setOverflowing] = React.useState(false)
  const measure = React.useCallback(() => {
    const element = ref.current
    if (!element) return
    // The 1px tolerance keeps a fractional content height from minting a
    // phantom tab stop on a field that cannot actually scroll.
    setOverflowing(element.scrollHeight - element.clientHeight > 1)
  }, [ref])
  React.useEffect(measure)
  React.useEffect(() => {
    const element = ref.current
    if (!element || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [measure, ref])
  return overflowing
}

export interface MessageApprovalProps
  extends Omit<
    React.ComponentProps<"div">,
    "title" | "children" | "onChange" | "onSelect"
  > {
  /** Who the message goes to — the display name, shown as the card's heading. */
  recipient: string
  /**
   * The draft itself. Editable cards keep their own copy of it, so this is
   * the text the person starts from; passing a new value reseeds the field.
   */
  message: string
  /**
   * The question above the card. Defaults to "Ready to send it?"; pass your
   * own wording (or a localized string) to replace it, or `null` when the
   * surrounding surface already asks.
   */
  title?: React.ReactNode
  /**
   * The app or service carrying the message, shown under the recipient's
   * name — "Messages", "WhatsApp", "SMS". Defaults to "Messages".
   */
  channel?: string
  /**
   * The channel's mark, badged on the avatar's corner. A card whose
   * `channel` names iMessage or Mail badges that service's own mark by
   * default; every other channel shows nothing until its host passes its
   * mark here. `null` suppresses the badge outright.
   */
  channelIcon?: React.ReactNode
  /**
   * Replaces the built-in avatar rendering entirely — a RandomAvatar, a
   * group stack, a brand mark. Takes precedence over `avatarSrc`.
   */
  avatar?: React.ReactNode
  /** Photo for the built-in avatar; `initials` show while it is absent or fails. */
  avatarSrc?: string
  /** Overrides the initials derived from `recipient`. */
  initials?: string
  /**
   * Whether the draft can be corrected in place, which it can by default:
   * a person who spots a wrong date should fix it here rather than start the
   * request again. The field grows with the text up to the card's cap and
   * scrolls past it; Enter breaks the line — a message is multi-line
   * content — while ⌘/Ctrl+Enter sends and Escape cancels. Pass `false` for
   * a draft the host owns outright, which renders as read-only text.
   */
  editable?: boolean
  /**
   * Called on every edit. Supplying it does not make the field controlled:
   * the card still owns the text, and this reports what it now holds. Use
   * it to persist a draft, not to filter keystrokes.
   */
  onMessageChange?: (message: string) => void
  /** Where the request stands. Defaults to `pending`. */
  status?: MessageApprovalStatus
  /** Replaces the resolved state's wording, including for localization. */
  statusLabel?: React.ReactNode
  /**
   * Called with the current text when the person sends. The host owns
   * delivery: move `status` to `sending`, then to `sent` or `failed`.
   */
  onSend?: (message: string) => void
  /** Called when the person cancels; the host owns what replaces the card. */
  onCancel?: () => void
  /** Send action's label. Defaults to "Send". */
  sendLabel?: string
  /** Cancel action's label. Defaults to "Cancel". */
  cancelLabel?: string
  /** Accessible name for the draft field. Defaults to "Message to {recipient}". */
  messageLabel?: string
}

/**
 * A send-confirmation card: an agent has written a message to someone and
 * asks before it goes out. The card names the recipient and the app it will
 * travel over, shows the draft — optionally editable in place — and offers
 * the two decisions, cancel and send.
 *
 * The card sizes itself to the container it is placed in rather than to the
 * viewport: in a narrow rail the actions stack with send on top, and from
 * about 20rem of width they sit side by side; past 24rem the avatar, padding,
 * and draft type step up. One card therefore works in a chat sidebar, a
 * composer dock, and a full-width panel without a size prop.
 *
 * Sending is the host's: `onSend` receives the current text, and `status`
 * drives the card through dispatch to its outcome, at which point the actions
 * give way to a status line that announces itself.
 */
function MessageApproval({
  recipient,
  message,
  title = "Ready to send it?",
  channel = "Messages",
  channelIcon,
  avatar,
  avatarSrc,
  initials,
  editable = true,
  onMessageChange,
  status = "pending",
  statusLabel,
  onSend,
  onCancel,
  sendLabel = "Send",
  cancelLabel = "Cancel",
  messageLabel,
  className,
  ...props
}: MessageApprovalProps) {
  const titleId = React.useId()
  const [draft, setDraft] = React.useState(message)
  // The host's text is the seed, not a controlled value: the field owns what
  // the person types, and a NEW draft from the host replaces it. Deriving it
  // during render (rather than in an effect) means the reseeded text paints
  // in the same commit, never a frame of the previous message.
  const [seed, setSeed] = React.useState(message)
  if (seed !== message) {
    setSeed(message)
    setDraft(message)
  }
  const fieldRef = React.useRef<HTMLDivElement>(null)
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const readOnlyOverflowing = useOverflowing(fieldRef)

  // The field grows with its content up to the cap set in CSS, then scrolls.
  // `field-sizing: content` does the same thing without JavaScript but is not
  // yet everywhere, and a draft that silently hides its own second line is
  // not something to leave to browser support.
  const resize = React.useCallback(() => {
    const textarea = textareaRef.current
    if (!textarea) return
    textarea.style.height = "auto"
    const cap = Number.parseFloat(getComputedStyle(textarea).maxHeight)
    const height = Number.isFinite(cap)
      ? Math.min(textarea.scrollHeight, cap)
      : textarea.scrollHeight
    textarea.style.height = `${height}px`
    textarea.style.overflowY =
      textarea.scrollHeight > height + 1 ? "auto" : "hidden"
  }, [])
  React.useLayoutEffect(resize, [resize, draft, editable])
  React.useEffect(() => {
    const textarea = textareaRef.current
    if (!textarea || typeof ResizeObserver === "undefined") return
    // Width changes rewrap the text and change how tall it wants to be; the
    // observer covers container resizes React never sees.
    let width = textarea.getBoundingClientRect().width
    const observer = new ResizeObserver(() => {
      const next = textarea.getBoundingClientRect().width
      if (next === width) return
      width = next
      resize()
    })
    observer.observe(textarea)
    return () => observer.disconnect()
  }, [resize, editable])

  const resolved = resolvedStatuses.has(status)
  const sending = status === "sending"
  const send = () => {
    if (resolved || sending) return
    onSend?.(draft)
  }
  const cancel = () => {
    if (resolved || sending) return
    onCancel?.()
  }

  // What the live region carries: the resolved wording, or "Sending…" while
  // the host dispatches. Nothing while the decision is still open — the card
  // is being read, not reported on. A host-supplied `statusLabel` replaces
  // the resolved wording in both places at once.
  const announcement = resolved
    ? (statusLabel ?? statusLabels[status])
    : sending
      ? statusLabels.sending
      : null

  // A built-in mark FILLS its badge, where a host's glyph sits inside one,
  // so the default carries its own tile geometry.
  const ownMark = channelIcon === undefined ? builtInChannelMark(channel) : null
  const badge = channelIcon === null ? null : (channelIcon ?? ownMark)
  // The draft's shared shape. No focus outline lives here: the two forms of
  // the field earn one differently, and only the read-only one gets it.
  const fieldClassName =
    "max-h-40 w-full min-w-0 whitespace-pre-wrap break-words rounded-xl bg-muted/60 px-3 py-2 font-sans nessa-text-3 text-foreground outline-none @[24rem]/message-approval:nessa-text-4"

  return (
    <div
      role="group"
      aria-labelledby={title == null ? undefined : titleId}
      aria-label={title == null ? `Send a message to ${recipient}` : undefined}
      data-slot="message-approval"
      data-status={status}
      className={cn(
        "@container/message-approval flex w-full min-w-0 flex-col gap-2 font-sans",
        className,
      )}
      {...props}
    >
      {title == null ? null : (
        <p
          id={titleId}
          data-slot="message-approval-title"
          className="min-w-0 nessa-text-3 font-medium text-foreground @[24rem]/message-approval:nessa-text-4"
        >
          {title}
        </p>
      )}
      <div
        data-slot="message-approval-card"
        className="flex min-w-0 flex-col gap-3 rounded-2xl border border-border bg-card p-3 text-card-foreground shadow-xs @[24rem]/message-approval:p-4"
      >
        <div
          data-slot="message-approval-recipient"
          className="flex min-w-0 items-center gap-2.5"
        >
          <ContactAvatar
            data-slot="message-approval-avatar"
            name={recipient}
            src={avatarSrc}
            initials={initials}
            badge={badge}
            className="size-9 @[24rem]/message-approval:size-10"
            badgeClassName={cn(
              ownMark != null
                ? // The logo IS the badge: it keeps its own rounded-square
                  // silhouette rather than being clipped into the circular
                  // tile a bare glyph sits in, and the card-coloured hairline
                  // separates it from the avatar behind it.
                  "-bottom-1 -right-1 size-[1.125rem] rounded-[0.3125rem] border-card bg-card [&_svg]:size-full @[24rem]/message-approval:size-5"
                : "@[24rem]/message-approval:size-[1.125rem] @[24rem]/message-approval:[&_svg]:size-3",
            )}
          >
            {avatar}
          </ContactAvatar>
          <span className="flex min-w-0 flex-col">
            <span
              data-slot="message-approval-name"
              className="truncate nessa-text-3 font-medium text-foreground @[24rem]/message-approval:nessa-text-4"
            >
              {recipient}
            </span>
            <span
              data-slot="message-approval-channel"
              className="truncate nessa-text-2 text-muted-foreground"
            >
              {channel}
            </span>
          </span>
        </div>
        {editable ? (
          <textarea
            ref={textareaRef}
            data-slot="message-approval-message"
            aria-label={messageLabel ?? `Message to ${recipient}`}
            rows={1}
            value={draft}
            readOnly={resolved || sending}
            onChange={(event) => {
              setDraft(event.target.value)
              onMessageChange?.(event.target.value)
            }}
            onKeyDown={(event) => {
              if (event.defaultPrevented) return
              if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
                event.preventDefault()
                // Same reasoning as Escape: a composer or transcript
                // listening for the send chord must not send twice.
                event.stopPropagation()
                send()
                return
              }
              if (event.key === "Escape") {
                event.preventDefault()
                // Abandoning the draft is the whole meaning of this
                // keystroke; a host sheet or overlay must not take it as a
                // dismissal of itself as well.
                event.stopPropagation()
                cancel()
              }
            }}
            // No focus ring on the editable field: the caret and selection
            // already show where focus is, and browsers match :focus-visible
            // on editable fields for pointer focus too — an outline here
            // would read as a permanent border around the draft rather than
            // as focus. This is the same call ChatComposer's textarea makes.
            className={cn(fieldClassName, "block resize-none overflow-hidden")}
          />
        ) : (
          <div
            ref={fieldRef}
            data-slot="message-approval-message"
            // A capped region that scrolls is keyboard-reachable, but only
            // while it has something to scroll to.
            role="region"
            aria-label={messageLabel ?? `Message to ${recipient}`}
            tabIndex={readOnlyOverflowing ? 0 : undefined}
            // The read-only region has no caret to show focus with, and it
            // takes a tab stop whenever it scrolls, so it keeps the ring.
            className={cn(
              fieldClassName,
              "overflow-y-auto focus-visible:[outline-style:solid] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
            )}
          >
            {message}
          </div>
        )}
        {/* The live region is mounted for the card's whole life, empty while
            the decision is open: a region inserted at the moment its text
            appears is a mutation most screen readers never announce. It is
            out of flow (sr-only is absolutely positioned), so it adds no
            row to the card's layout. */}
        <span
          role="status"
          aria-live="polite"
          data-slot="message-approval-announcement"
          className="sr-only"
        >
          {announcement}
        </span>
        {resolved ? (
          <p
            data-slot="message-approval-status"
            className={cn(
              // Aligned to the reading edge, where the send action was: the
              // outcome lands under the control that produced it rather than
              // in the opposite corner.
              "flex min-w-0 items-center justify-end gap-1.5 nessa-text-2",
              status === "failed" ? "text-destructive" : "text-muted-foreground",
            )}
          >
            {React.createElement(statusIcons[status as keyof typeof statusIcons], {
              "aria-hidden": "true",
              className: "size-3.5 shrink-0",
            })}
            <span className="min-w-0 truncate">
              {statusLabel ?? statusLabels[status]}
            </span>
          </p>
        ) : (
          // Reversed so the stacked order puts send on top — the choice the
          // person came for — while the row order keeps cancel at the start
          // and send at the reading edge.
          <div
            data-slot="message-approval-actions"
            className="flex flex-col-reverse gap-2 @[20rem]/message-approval:flex-row"
          >
            <Button
              type="button"
              variant="secondary"
              disabled={sending}
              onClick={cancel}
              className="flex-1"
            >
              {cancelLabel}
            </Button>
            <Button
              type="button"
              disabled={sending}
              onClick={send}
              // The send blue is the chat identity, the same fixed accent
              // ChatBubble paints a sent message with — not the theme's
              // primary, which would drift from the transcript it belongs to.
              className="flex-1 bg-(--nessa-chat-accent) text-white hover:bg-(--nessa-chat-accent)/90"
            >
              {sending ? (
                <LoaderCircle
                  aria-hidden="true"
                  className="animate-spin [animation-duration:var(--nessa-motion-duration-ambient)] motion-reduce:animate-none"
                />
              ) : null}
              {sending ? statusLabels.sending : sendLabel}
            </Button>
          </div>
        )}
      </div>
    </div>
  )
}

export { MessageApproval }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { ContactAvatar } from "./contact-avatar"

export interface MessageDigestEntry {
  /** Identifies the message across selection. */
  id: string
  /** Who it is from — the row's heading. */
  sender: string
  /** The subject or thread title, under the sender. */
  subject?: string
  /** The opening of the message, clamped to `previewLines`. */
  preview?: string
  /** When it arrived, already formatted by the host — "8:42 AM", "Tue". */
  timestamp?: string
  /** Marks the row unread: a dot on the leading edge and a bolder sender. */
  unread?: boolean
  /** Photo for the row's avatar; initials show while it is absent or fails. */
  avatarSrc?: string
  /** Overrides the initials derived from `sender`. */
  initials?: string
  /** A glyph badged on the avatar — the account or app it arrived on. */
  badge?: React.ReactNode
  /**
   * What that badge means, in words — "work account". The mark is drawn as
   * decoration and a digest row writes no channel text of its own, so a
   * badge that distinguishes one account from another needs this to reach
   * anyone who cannot see it.
   */
  badgeLabel?: string
}

/** Static classes, so Tailwind's scanner sees every clamp the API allows. */
const previewClampClasses = {
  1: "line-clamp-1",
  2: "line-clamp-2",
  3: "line-clamp-3",
} as const

export interface MessageDigestProps
  extends Omit<React.ComponentProps<"div">, "onSelect" | "title" | "children"> {
  /** The messages to list, in the order the host wants them read. */
  messages: readonly MessageDigestEntry[]
  /** A line above the list — what the agent was asked, or what it found. */
  title?: React.ReactNode
  /**
   * Opens a message. Supplying it makes every row a button; without it the
   * rows are quiet summary tiles, which is what a cited result usually is.
   */
  onValueChange?: (id: string) => void
  /** The opened message's id, marked `aria-current` while rows are buttons. */
  value?: string | null
  /** How many lines of `preview` survive before the text clamps. Defaults to 2. */
  previewLines?: 1 | 2 | 3
  /**
   * Accessible name for the list. Defaults to the title when it is a plain
   * string, and to "Messages" otherwise.
   */
  label?: string
  /** Shown in place of the list when `messages` is empty. */
  emptyMessage?: string
}

/**
 * What an agent found in someone's inbox, as the rows a mail app would draw:
 * sender, subject, the opening of the message, and when it landed, with unread
 * ones dotted on the leading edge. It is a reading surface by default — pass
 * `onValueChange` when the host can actually open a message and every row
 * becomes a button.
 *
 * The rows size themselves to their container rather than the viewport: the
 * timestamp keeps its place at the end of the sender line at every width, the
 * subject truncates, and the preview clamps to `previewLines`, so a digest
 * reads the same in a narrow rail as in a full-width panel. Ordering,
 * filtering, and formatting the timestamp stay with the host.
 */
function MessageDigest({
  messages,
  title,
  onValueChange,
  value = null,
  previewLines = 2,
  label,
  emptyMessage = "No messages",
  className,
  ...props
}: MessageDigestProps) {
  const titleId = React.useId()
  // The title element names the list when there is one; `label` overrides
  // it, and a digest with no title falls back to the generic word.
  const titled = title != null && label === undefined
  const interactive = onValueChange !== undefined
  return (
    <div
      data-slot="message-digest"
      className={cn(
        "@container/message-digest flex w-full min-w-0 flex-col gap-2 font-sans",
        className,
      )}
      {...props}
    >
      {title == null ? null : (
        <p
          id={titleId}
          data-slot="message-digest-title"
          className="min-w-0 nessa-text-3 font-medium text-foreground @[24rem]/message-digest:nessa-text-4"
        >
          {title}
        </p>
      )}
      {messages.length === 0 ? (
        <p className="m-0 px-1 py-4 nessa-text-3 text-muted-foreground">
          {emptyMessage}
        </p>
      ) : (
        <ul
          role="list"
          aria-labelledby={titled ? titleId : undefined}
          aria-label={titled ? undefined : (label ?? "Messages")}
          data-slot="message-digest-list"
          className="m-0 flex list-none flex-col gap-2 p-0"
        >
          {messages.map((message) => {
            const selected = interactive && message.id === value
            const rowClassName = cn(
              "flex w-full min-w-0 items-start gap-2.5 rounded-2xl border-0 bg-muted/60 px-3 py-2.5 text-start @[24rem]/message-digest:gap-3 @[24rem]/message-digest:px-3.5 @[24rem]/message-digest:py-3",
              interactive &&
                "outline-none transition-colors [transition-duration:var(--nessa-motion-duration-fast)] hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:transition-none",
              selected && "bg-accent text-accent-foreground",
            )
            const content = (
              <>
                {/* Unread rides the avatar's corner rather than a column of
                    its own: a leading dot costs every row its indent for a
                    mark most rows do not carry. It repeats what the sr-only
                    word already says, so it stays decoration. */}
                <ContactAvatar
                  name={message.sender}
                  src={message.avatarSrc}
                  initials={message.initials}
                  badge={message.badge}
                  unread={message.unread}
                  className="size-8 @[24rem]/message-digest:size-9"
                />
                {/* The three ranks need air between them: line boxes that butt
                    straight into each other read as one paragraph rather than
                    sender, subject, and preview. */}
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="flex min-w-0 items-baseline gap-2">
                    <span
                      data-slot="message-digest-sender"
                      className={cn(
                        "min-w-0 flex-1 truncate nessa-text-3 text-foreground",
                        message.unread ? "font-semibold" : "font-medium",
                      )}
                    >
                      {message.unread ? (
                        <span className="sr-only">Unread. </span>
                      ) : null}
                      {message.sender}
                      {message.badgeLabel == null ? null : (
                        // After the sender, so the row reads "Lois Lane work
                        // account" — the badge is decoration and this is the
                        // only place its meaning exists in text.
                        <span className="sr-only"> {message.badgeLabel}</span>
                      )}
                    </span>
                    {message.timestamp ? (
                      <span
                        data-slot="message-digest-timestamp"
                        className="shrink-0 nessa-text-1 text-muted-foreground"
                      >
                        {message.timestamp}
                      </span>
                    ) : null}
                  </span>
                  {message.subject ? (
                    <span
                      data-slot="message-digest-subject"
                      className="min-w-0 truncate nessa-text-2 font-medium text-foreground"
                    >
                      {message.subject}
                    </span>
                  ) : null}
                  {message.preview ? (
                    <span
                      data-slot="message-digest-preview"
                      className={cn(
                        "min-w-0 nessa-text-2 text-muted-foreground",
                        previewClampClasses[previewLines],
                      )}
                    >
                      {message.preview}
                    </span>
                  ) : null}
                </span>
              </>
            )
            return (
              <li key={message.id} className="min-w-0">
                {interactive ? (
                  <button
                    type="button"
                    aria-current={selected ? "true" : undefined}
                    data-slot="message-digest-item"
                    data-unread={message.unread || undefined}
                    onClick={() => onValueChange?.(message.id)}
                    className={rowClassName}
                  >
                    {content}
                  </button>
                ) : (
                  <div
                    data-slot="message-digest-item"
                    data-unread={message.unread || undefined}
                    className={rowClassName}
                  >
                    {content}
                  </div>
                )}
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}

export { MessageDigest }
